// personaUseBridge (#change-a-panes-persona-from-the-cli) — decide what a `bsc persona use` request
// does to the store.
//
// Pure on purpose: the DECISION (does the persona exist, what was it before, does this need a relaunch)
// is testable without Tauri or a rendered app, and the listener stays a thin adapter — the same split
// `fleetWakeBridge` and `navigateBridge` use.
//
// WHY A RELAUNCH IS PART OF THE VERB
// The persona is the LAUNCH primitive: capability, MCP servers and hooks are all resolved from it when
// the session starts (`session-launch.ts` reads `panePersonas` before `paneRoles`, because a persona's
// floor may be narrower than its role's). So writing the map under a running session changes nothing the
// agent can observe. A `use` that only wrote the map would report success for a no-op, which is the same
// class of lie #4025 was: a caller told the thing landed when it had not.
//
// WHY THE KILL IS HERE
// `wakePane` does NOT kill — it bakes the startup prompt and bumps the owning tab's runId, and on
// reconnect `pty_create` discards the baked prompt (the #3998 init_cmd-on-reconnect trap). So a pane
// whose shell outlived its agent would reconnect to bash and never relaunch under the new identity.
// Kill first, exactly as `applyWake` does, so the remount SPAWNS.

/** The request as it arrives from Rust (`bsc://persona-use`). */
export interface PersonaUseRequest {
  paneId: string;
  personaId: string;
  /** Restart the session so the new identity is in effect. */
  relaunch: boolean;
  /** Carried for completeness; the BUSY refusal it governs is applied in Rust, before this is emitted. */
  force?: boolean;
}

/** What we send back via `persona_use_ack`. */
export interface PersonaUseAck {
  id: string;
  error?: string;
  applied: boolean;
  previous?: string;
  relaunched: boolean;
}

/** The store surface this needs — narrowed so the pure fn stays decoupled from the slice. */
export interface PersonaUseDeps {
  /** Every persona id the library holds. The CLI checks the STORE; this checks what the app actually
   *  hydrated, which is the set a launch can resolve against. */
  personaIds: () => string[];
  /** The pane's current persona, or undefined. Reported back so the change is reversible. */
  currentPersona: (paneId: string) => string | undefined;
  /** The real `setPanePersona`. */
  setPanePersona: (paneId: string, personaId: string) => void;
  /** `pty_kill` for this pane. MUST run before the wake so the remount spawns rather than reconnecting
   *  — see the header. A no-op when there is no PTY. */
  killPane: (paneId: string) => Promise<void>;
  /** The real `wakePane` — bumps the owning tab's runId, which remounts the pane. Returns whether it
   *  resolved a tab at all. */
  wakePane: (paneId: string, prompt: string) => boolean;
}

/**
 * What a relaunched session is told. A persona change is not a task, so this states the change rather
 * than inventing work — an empty prompt would drop the agent at a prompt with nothing to do.
 */
export const PERSONA_CHANGE_PROMPT =
  "Your persona has been changed. Re-read your instructions and continue under the new identity.";

/**
 * Apply one request. Total over its OWN paths — bad input, an unknown persona and a kill that fails all
 * produce an ack rather than an exception, because silence would strand the Rust waiter until its
 * timeout and surface as "the frontend did not apply the persona", sending someone to debug the wrong
 * thing. A DEP that throws propagates on purpose: swallowing it here would hide a real bug, and the
 * listener wraps the call so an ack still goes back.
 */
export async function applyPersonaUse(
  id: string,
  req: PersonaUseRequest,
  deps: PersonaUseDeps,
): Promise<PersonaUseAck> {
  const paneId = (req.paneId ?? "").trim();
  const personaId = (req.personaId ?? "").trim();
  if (!paneId) return { id, error: "persona use: no pane id", applied: false, relaunched: false };
  if (!personaId) return { id, error: "persona use: no persona id", applied: false, relaunched: false };

  // Checked again HERE, and not only in the CLI: the CLI reads the store on disk, while a launch
  // resolves against the library the app hydrated. Those can differ (a persona written after this app
  // started, one removed since), and the set that matters is the one a launch can actually find.
  const known = deps.personaIds();
  if (!known.includes(personaId)) {
    return {
      id,
      error:
        `persona use: the app's library has no persona '${personaId}'` +
        (known.length ? ` — known: ${known.join(", ")}` : " — its persona library is empty"),
      applied: false,
      relaunched: false,
    };
  }

  const previous = deps.currentPersona(paneId);
  deps.setPanePersona(paneId, personaId);

  if (!req.relaunch) {
    // Staged, not applied. The CLI says which happened, so this is not a silent half-measure.
    return { id, applied: true, previous, relaunched: false };
  }

  // A kill failure must not abort the relaunch: the common reason is that there was nothing to kill,
  // and refusing to relaunch a dormant pane because its absent PTY could not be killed would break
  // exactly the case where changing a persona is cheapest.
  await deps.killPane(paneId).catch(() => {});
  const relaunched = deps.wakePane(paneId, PERSONA_CHANGE_PROMPT);
  // The assignment landed either way — `applied` is about the map, `relaunched` about the session — so a
  // pane with no open tab still reports the truth rather than looking like a total failure.
  return { id, applied: true, previous, relaunched };
}

